def bowling_score(rolls):
    # Validate each roll is an integer between 0 and 10
    if any(not isinstance(r, int) or r < 0 or r > 10 for r in rolls):
        raise ValueError("Invalid roll value")

    score = 0
    i = 0

    for frame in range(10):
        if frame < 9:
            # Frames 1-9
            if i >= len(rolls):
                raise ValueError("Too few rolls")

            first = rolls[i]

            if first == 10:
                # Strike: needs two bonus rolls
                if i + 2 >= len(rolls):
                    raise ValueError("Too few rolls for strike bonus")
                score += 10 + rolls[i + 1] + rolls[i + 2]
                i += 1
            else:
                # Not a strike: needs a second roll
                if i + 1 >= len(rolls):
                    raise ValueError("Too few rolls")
                second = rolls[i + 1]

                if first + second > 10:
                    raise ValueError("Frame rolls exceed 10")

                if first + second == 10:
                    # Spare: needs one bonus roll
                    if i + 2 >= len(rolls):
                        raise ValueError("Too few rolls for spare bonus")
                    score += 10 + rolls[i + 2]
                else:
                    score += first + second

                i += 2
        else:
            # Tenth frame
            if i >= len(rolls):
                raise ValueError("Too few rolls")

            first = rolls[i]

            if first == 10:
                # Strike: needs two bonus rolls
                if i + 2 >= len(rolls):
                    raise ValueError("Too few rolls for strike bonus")
                score += 10 + rolls[i + 1] + rolls[i + 2]
                i += 3
            else:
                # Needs a second roll
                if i + 1 >= len(rolls):
                    raise ValueError("Too few rolls")
                second = rolls[i + 1]

                if first + second > 10:
                    raise ValueError("Frame rolls exceed 10")

                if first + second == 10:
                    # Spare: needs one bonus roll
                    if i + 2 >= len(rolls):
                        raise ValueError("Too few rolls for spare bonus")
                    score += 10 + rolls[i + 2]
                    i += 3
                else:
                    score += first + second
                    i += 2

    if i != len(rolls):
        raise ValueError("Too many rolls")

    return score
